    long long res = 1;
    a %= mod;
    while (b > 0) {
        if (b & 1) {
            res = res * a % mod;
        }
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

// 计算答案
long long solve(const string& x, long long mod) {
    long long p = 0;

    // 统计分子 p = sum(9 - 当前位数字)
    for (char ch : x) {
        int d = ch - '0';
        p = (p + 9 - d) % mod;
    }

    // 分母 q = 10 * n
    long long q = 10LL * x.size() % mod;

    // 求逆元
    long long qInv = qpow(q, mod - 2, mod);

    // 返回结果
    return p * qInv % mod;
}

int main() {
    string x;
    long long mod;
    cin >> x >> mod;
    cout << solve(x, mod) << '\n';
    return 0;
}
